package com.receiptledger.v1.recovery;

import android.graphics.*;import com.receiptledger.v1.document.*;

public final class ReceiptImagePreprocessor {
 public static final int MAX_EDGE=3200;public static final long MAX_PIXELS=6_000_000L;private ReceiptImagePreprocessor(){}
 public static PreparedImage prepareContrast(Bitmap input,ProjectiveTransform inputToSource){RecoveryScalePlanner.Plan p=RecoveryScalePlanner.plan(input.getWidth(),input.getHeight(),MAX_EDGE,MAX_PIXELS);Bitmap out=Bitmap.createBitmap(p.width,p.height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(out);Paint paint=new Paint(Paint.FILTER_BITMAP_FLAG);canvas.drawBitmap(input,null,new Rect(0,0,p.width,p.height),paint);stretchContrast(out);PointD[] r={new PointD(0,0),new PointD(p.width-1.0,0),new PointD(p.width-1.0,p.height-1.0),new PointD(0,p.height-1.0)};PointD[] source={inputToSource.map(new PointD(0,0)),inputToSource.map(new PointD(input.getWidth()-1.0,0)),inputToSource.map(new PointD(input.getWidth()-1.0,input.getHeight()-1.0)),inputToSource.map(new PointD(0,input.getHeight()-1.0))};return new PreparedImage(out,ProjectiveTransform.fromFourPoints(r,source));}
 public static void adaptiveBinaryInPlace(Bitmap b){final int tile=64;for(int y=0;y<b.getHeight();y+=tile){int h=Math.min(tile,b.getHeight()-y);for(int x=0;x<b.getWidth();x+=tile){int w=Math.min(tile,b.getWidth()-x),n=w*h;int[] px=new int[n];b.getPixels(px,0,w,x,y,w,h);long sum=0;for(int c:px)sum+=luma(c);int threshold=(int)(sum/Math.max(1,n))-8;for(int i=0;i<n;i++){int v=luma(px[i])>threshold?255:0;px[i]=Color.rgb(v,v,v);}b.setPixels(px,0,w,x,y,w,h);}}}
 private static void stretchContrast(Bitmap b){int[] hist=new int[256];int w=b.getWidth(),h=b.getHeight();int[] row=new int[w];long count=0;int stride=Math.max(1,(int)Math.sqrt((w*(long)h)/1_500_000.0));for(int y=0;y<h;y+=stride){b.getPixels(row,0,w,0,y,w,1);for(int x=0;x<w;x+=stride){hist[luma(row[x])]++;count++;}}int low=percentile(hist,count,0.02),high=percentile(hist,count,0.98);if(high-low<24){low=Math.max(0,low-12);high=Math.min(255,high+12);}int range=Math.max(1,high-low);for(int y=0;y<h;y++){b.getPixels(row,0,w,0,y,w,1);for(int x=0;x<w;x++){int v=(luma(row[x])-low)*255/range;if(v<0)v=0;else if(v>255)v=255;row[x]=Color.rgb(v,v,v);}b.setPixels(row,0,w,0,y,w,1);}}
 private static int percentile(int[] h,long total,double p){long target=Math.max(0,Math.round(total*p)),sum=0;for(int i=0;i<h.length;i++){sum+=h[i];if(sum>=target)return i;}return 255;}private static int luma(int c){return (77*Color.red(c)+150*Color.green(c)+29*Color.blue(c))>>8;}
 public static final class PreparedImage{public final Bitmap bitmap;public final ProjectiveTransform inputToSource;PreparedImage(Bitmap b,ProjectiveTransform m){bitmap=b;inputToSource=m;}}
}
